1	package events
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"time"
9	)
10	
11	// eventDTO is the wire and on-disk representation of an event. Timestamps use
12	// RFC3339Nano, which time.Time produces and accepts natively. Labels is
13	// omitted entirely when an event has none, so frames written before labels
14	// existed decode unchanged.
15	type eventDTO struct {
16		ID       string            `json:"id"`
17		Service  string            `json:"service"`
18		Severity string            `json:"severity"`
19		Message  string            `json:"message"`
20		At       time.Time         `json:"at"`
21		Labels   map[string]string `json:"labels,omitempty"`
22	}
23	
24	// decodeLabels strictly decodes a JSON labels member; DecodeLabelsObject is
25	// the exported form used by request bodies that carry the same shape, such as
26	// the label filters in an alert preview request.
27	func decodeLabels(raw json.RawMessage) (map[string]string, error) {
28		return DecodeLabelsObject(raw)
29	}
30	
31	// DecodeLabelsObject strictly decodes a JSON labels object: null, absent, or
32	// an object whose values are all strings, and duplicate names are rejected
33	// instead of silently overwriting each other the way a plain map decode
34	// would. Name/value content rules are enforced later by NormalizeLabels or
35	// filter normalization.
36	func DecodeLabelsObject(raw json.RawMessage) (map[string]string, error) {
37		if len(raw) == 0 || bytes.Equal(raw, []byte("null")) {
38			return nil, nil
39		}
40		dec := json.NewDecoder(bytes.NewReader(raw))
41		open, err := dec.Token()
42		if err != nil {
43			return nil, fmt.Errorf("decode labels: %w", err)
44		}
45		if delim, ok := open.(json.Delim); !ok || delim != '{' {
46			return nil, fmt.Errorf("decode labels: must be an object of string values")
47		}
48		labels := make(map[string]string)
49		for dec.More() {
50			keyToken, err := dec.Token()
51			if err != nil {
52				return nil, fmt.Errorf("decode labels: %w", err)
53			}
54			key, ok := keyToken.(string)
55			if !ok {
56				return nil, fmt.Errorf("decode labels: names must be strings")
57			}
58			if _, dup := labels[key]; dup {
59				return nil, fmt.Errorf("decode labels: duplicate label name %q", key)
60			}
61			var value *string
62			if err := dec.Decode(&value); err != nil {
63				return nil, fmt.Errorf("decode labels: value for %q must be a string", key)
64			}
65			if value == nil {
66				return nil, fmt.Errorf("decode labels: value for %q must be a string", key)
67			}
68			labels[key] = *value
69		}
70		if _, err := dec.Token(); err != nil { // closing '}'
71			return nil, fmt.Errorf("decode labels: %w", err)
72		}
73		if len(labels) == 0 {
74			return nil, nil
75		}
76		return labels, nil
77	}
78	
79	// allowedEventFields is the exact set of members each event object may
80	// carry; anything else is an unknown field.
81	var allowedEventFields = map[string]struct{}{
82		"id":       {},
83		"service":  {},
84		"severity": {},
85		"message":  {},
86		"at":       {},
87		"labels":   {},
88	}
89	
90	// MarshalBatch encodes normalized events as a JSON array with sorted keys.
91	func MarshalBatch(batch []Event) ([]byte, error) {
92		dtos := make([]eventDTO, len(batch))
93		for i, event := range batch {
94			dtos[i] = eventDTO{
95				ID:       event.ID,
96				Service:  event.Service,
97				Severity: event.Severity,
98				Message:  event.Message,
99				At:       event.At,
100				Labels:   event.Labels,
101			}
102		}
103		return json.Marshal(dtos)
104	}
105	
106	// DecodeBatch strictly decodes a JSON array of events. Unknown fields,
107	// syntax errors, malformed timestamps, malformed labels, trailing data, and
108	// duplicate member names within the outer array's event objects are
109	// rejected; callers remain responsible for emptiness and field validation.
110	// Names are compared after JSON decoding, so a literal name and its \uXXXX
111	// escape of the same text count as a repeat.
112	func DecodeBatch(data []byte) ([]Event, error) {
113		dec := json.NewDecoder(bytes.NewReader(data))
114		open, err := dec.Token()
115		if err != nil {
116			return nil, fmt.Errorf("decode events array: %w", err)
117		}
118		if delim, ok := open.(json.Delim); !ok || delim != '[' {
119			return nil, fmt.Errorf("decode events array: must be an array of event objects")
120		}
121	
122		var batch []Event
123		for dec.More() {
124			event, err := decodeEventObject(dec)
125			if err != nil {
126				return nil, err
127			}
128			batch = append(batch, event)
129		}
130	
131		if _, err := dec.Token(); err != nil { // closing ']'
132			return nil, fmt.Errorf("decode events array: %w", err)
133		}
134		var extra json.RawMessage
135		if err := dec.Decode(&extra); err != io.EOF {
136			if err == nil {
137				return nil, fmt.Errorf("decode events array: unexpected trailing data")
138			}
139			return nil, fmt.Errorf("decode events array: %w", err)
140		}
141		return batch, nil
142	}
143	
144	// decodeEventObject reads one event object from dec, rejecting unknown
145	// members and repeated member names (after JSON unescaping). Values retain
146	// the same typed-decoding behavior as a struct decode: strings, RFC3339
147	// timestamps, and the strict labels shape.
148	func decodeEventObject(dec *json.Decoder) (Event, error) {
149		var event Event
150		open, err := dec.Token()
151		if err != nil {
152			return Event{}, fmt.Errorf("decode events array: %w", err)
153		}
154		if delim, ok := open.(json.Delim); !ok || delim != '{' {
155			return Event{}, fmt.Errorf("decode events array: each entry must be an object")
156		}
157	
158		seen := make(map[string]struct{})
159		for dec.More() {
160			keyToken, err := dec.Token()
161			if err != nil {
162				return Event{}, fmt.Errorf("decode events array: %w", err)
163			}
164			key, ok := keyToken.(string)
165			if !ok {
166				return Event{}, fmt.Errorf("decode events array: event field names must be strings")
167			}
168			if _, known := allowedEventFields[key]; !known {
169				return Event{}, fmt.Errorf("decode events array: unknown field %q", key)
170			}
171			if _, dup := seen[key]; dup {
172				return Event{}, fmt.Errorf("decode events array: duplicate field %q", key)
173			}
174			seen[key] = struct{}{}
175	
176			switch key {
177			case "id":
178				if err := dec.Decode(&event.ID); err != nil {
179					return Event{}, fmt.Errorf("decode events array: id has the wrong type")
180				}
181			case "service":
182				if err := dec.Decode(&event.Service); err != nil {
183					return Event{}, fmt.Errorf("decode events array: service has the wrong type")
184				}
185			case "severity":
186				if err := dec.Decode(&event.Severity); err != nil {
187					return Event{}, fmt.Errorf("decode events array: severity has the wrong type")
188				}
189			case "message":
190				if err := dec.Decode(&event.Message); err != nil {
191					return Event{}, fmt.Errorf("decode events array: message has the wrong type")
192				}
193			case "at":
194				if err := dec.Decode(&event.At); err != nil {
195					return Event{}, fmt.Errorf("decode events array: at must be an RFC3339Nano timestamp")
196				}
197			case "labels":
198				var raw json.RawMessage
199				if err := dec.Decode(&raw); err != nil {
