// Package strictjson holds the structural JSON rules shared by the batch
// ingesters and request-body decoders: every object is read as a sequence of
// uniquely named members, where names are compared after JSON decoding (so a
// literal name and its \uXXXX escape of the same text repeat), unknown names
// are rejected, and each document is exactly one complete value with no
// tokens trailing it. Only the structure is shared: callers keep every
// domain meaning and type rule for the values they read.
package strictjson

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
)

// ReadObject reads exactly one JSON object from dec, returning each member's
// raw value keyed by its decoded name. Names repeat on their decoded text,
// including across literal/Unicode-escape spellings, and (when allowed is
// non-nil) names outside allowed are unknown fields; both reject the whole
// object. Pass a nil allowed to accept any member name. Values are not
// examined, so null keeps its raw token for the caller to interpret.
func ReadObject(dec *json.Decoder, what string, allowed map[string]struct{}) (map[string]json.RawMessage, error) {
	open, err := dec.Token()
	if err != nil {
		return nil, fmt.Errorf("%s: %w", what, err)
	}
	if delim, ok := open.(json.Delim); !ok || delim != '{' {
		return nil, fmt.Errorf("%s: must be a JSON object", what)
	}
	fields := make(map[string]json.RawMessage)
	for dec.More() {
		keyToken, err := dec.Token()
		if err != nil {
			return nil, fmt.Errorf("%s: %w", what, err)
		}
		key, ok := keyToken.(string)
		if !ok {
			return nil, fmt.Errorf("%s: member names must be strings", what)
		}
		if allowed != nil {
			if _, known := allowed[key]; !known {
				return nil, fmt.Errorf("%s: unknown field %q", what, key)
			}
		}
		if _, dup := fields[key]; dup {
			return nil, fmt.Errorf("%s: duplicate field %q", what, key)
		}
		var raw json.RawMessage
		if err := dec.Decode(&raw); err != nil {
			return nil, fmt.Errorf("%s: %w", what, err)
		}
		fields[key] = raw
	}
	if _, err := dec.Token(); err != nil { // closing '}'
		return nil, fmt.Errorf("%s: %w", what, err)
	}
	return fields, nil
}

// DecodeObject strictly decodes data as exactly one JSON object, rejecting
// anything following the closing brace.
func DecodeObject(data []byte, what string, allowed map[string]struct{}) (map[string]json.RawMessage, error) {
	dec := json.NewDecoder(bytes.NewReader(data))
	fields, err := ReadObject(dec, what, allowed)
	if err != nil {
		return nil, err
	}
	if err := NoTrailingData(dec, what); err != nil {
		return nil, err
	}
	return fields, nil
