func TestVisitOrderMatchesStream(t *testing.T) {
	var order []string
	dec := json.NewDecoder(strings.NewReader(`{"z":1,"a":2,"m":3}`))
	err := EachObjectField(dec, "test object", nil, func(key string, _ json.RawMessage) error {
